entries[442489] = { ["name"] = "Warding Threads", ["text"] = "Instant\nTaking magic damage has a chance for the webbing to react and adapt, spinning Warding Threads around you for 30 sec. While active, Warding Threads absorb all damage you would take from that source's spell school, up to 9176 . (2 min Cooldown)" }
